          }
        },
        {
          "@type": "Question",
          "name": "How long does trademark opposition take in Pune?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The complete process typically takes 2-4 years from filing to final decision. The initial opposition window is 4 months from journal publication. The applicant has 2 months for a counter statement. Evidence submission and hearings add 6-18 months. Online hearings at the Mumbai Registry have helped reduce delays."
          }
        },
        {
          "@type": "Question",
          "name": "What happens if I do not file a counter statement?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Under the Trade Marks Rules, 2017, if the applicant fails to file a counter statement within 2 months of receiving the opposition notice, the trademark application is deemed abandoned and the mark will not proceed to registration."
          }
        },
        {
          "@type": "Question",
          "name": "Can I oppose a trademark even if my own mark is not registered?",
          "acceptedAnswer": {
            "@type": "Answer",
